def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w)
               if all(grid[r][c] == grid[0][c] for r in range(h)))
    n = sep
    left = [row[:n] for row in grid]
    right = [row[sep + 1:sep + 1 + n] for row in grid]

    def most_common(values):
        return max(set(values), key=values.count)

    left_bg = most_common([x for row in left for x in row])
    right_bg = most_common([x for row in right for x in row])

    return [[3 if left[r][c] != left_bg and right[r][c] == right_bg
             else right_bg for c in range(n)] for r in range(h)]
